import {icon} from './icons.js';
import {KEYSTONE_RARITIES} from './loot.js';
import {CRAFT_OPERATIONS} from './crafting.js';
import {KEYSTONE_RECIPES,RIFT_MODIFIERS,modifierValue,riftBonuses} from './keystones.js';

const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function keystoneDetails(key){
  const b=riftBonuses(key);
  return `<div class="keystone-detail rarity-${key.rarity}"><span class="item-rarity">${KEYSTONE_RARITIES[key.rarity]} · KEYSTONE · LEVEL ${key.itemLevel}</span><h3>${esc(key.name)}</h3><p class="dialog-description">Four monster waves, then a powerful rift guardian. Each wave starts as soon as the previous wave is cleared.</p><div class="rift-rewards"><div><strong>${key.itemLevel+b.itemLevel}</strong><span>Reward item level</span></div><div><strong>+${b.quantity}%</strong><span>Item quantity</span></div><div><strong>+${b.rarity}%</strong><span>Item rarity</span></div></div><h4>Rift difficulty</h4><div class="rift-difficulty">${[['Monster life',b.life],['Monster damage',b.damage],['Movement & attack speed',b.speed],['Monsters per wave',b.pack],['Damage reduction',b.reduction],['Critical chance (points)',b.critical]].filter(([,v])=>v).map(([label,value])=>`<div><span>${label}</span><b>+${value}%</b></div>`).join('')}</div><h4>Rolled modifiers · ${key.modifiers.length}</h4><ul class="rift-modifiers">${key.modifiers.length?key.modifiers.map(m=>`<li><strong>${RIFT_MODIFIERS[m.id].name}</strong><span>+${modifierValue(m)}% ${RIFT_MODIFIERS[m.id].label}</span></li>`).join(''):'<li>No rolled modifiers. This rift still has stronger monsters and a final boss.</li>'}</ul><p class="small-description">Every rolled modifier raises reward item level, quantity, and rarity. Quantity grants extra item rolls; rarity improves the chance of better equipment and does not guarantee a rarity.</p><p class="rift-rule">One entry. Opening consumes the keystone; entering consumes the portal. Death or teleporting out ends the run. Reloading resumes an unfinished run; rifts pause while you are away.</p></div>`;
}
export function keystonePouch(s,page=0){
  const pages=Math.max(1,Math.ceil(s.keystones.length/12));page=Math.max(0,Math.min(pages-1,page));
  const items=s.keystones.slice(page*12,page*12+12);
  return `<section class="panel secondary-panel keystone-pouch"><div class="view-section-title"><div><h2>Keystone pouch <span class="capacity">${s.keystones.length}</span></h2><p>Rare finds, stored separately from equipment. Keystones always pass your loot filter.</p></div>${icon('gem')}</div><div class="keystone-grid">${items.map(k=>{const b=riftBonuses(k);return `<button class="keystone-card rarity-${k.rarity}" data-keystone="${k.id}"><span class="item-rarity">${KEYSTONE_RARITIES[k.rarity]} · LEVEL ${k.itemLevel}</span>${icon('gem')}<strong>${esc(k.name)}</strong><span>${k.modifiers.length} modifiers · reward level ${k.itemLevel+b.itemLevel}</span><small>+${b.quantity}% quantity · +${b.rarity}% rarity</small><b>Inspect ${icon('arrow')}</b></button>`;}).join('')||'<p class="village-empty">No keystones yet. Find them on defeated foes, or use orbs at the Village’s keystone altar.</p>'}</div>${pages>1?`<div class="pouch-pagination"><button class="button" data-key-page="${page-1}" ${page===0?'disabled':''}>Previous</button><span>${page+1} / ${pages}</span><button class="button" data-key-page="${page+1}" ${page===pages-1?'disabled':''}>Next</button></div>`:''}</section>`;
}
export function villagePanel(s,page=0){
  const last=s.lastRift,status=last?.status;
  const notice=last?status==='cleared'?'Rift conquered. Your collected rewards are safe.':status==='failed'?'You fell in the rift. That portal is permanently closed.':status==='lost'?'The saved rift could not be restored. Its portal remains consumed.':'You left the rift. That portal is permanently closed.':'';
  return `<section class="village-welcome panel"><div><span class="eyebrow">VILLAGE · A PLACE TO RETURN TO</span><h2>Rest beneath the lanterns.</h2><p>The wild can wait. Prepare your gear, shape a keystone, and choose your next journey.</p><span class="village-safe">${icon('shield')} Safe in town · combat and offline farming paused</span></div><div class="village-services"><button class="button" data-view="forge">${icon('hammer')} Village forge</button><button class="button" data-view="inventory">${icon('bag')} Open satchel</button></div></section>${notice?`<p class="rift-result" role="status">${icon(status==='cleared'?'trophy':'info')}${notice}</p>`:''}<div class="village-routes"><section class="panel village-route"><span class="route-number">01 · THE ROAD</span><h3>Expedition entrance</h3><p>Start a fresh map of any unlocked stage. Your highest unlocked stage is ${s.maxStage}.</p><form id="village-stage-form"><label for="village-stage">Stage</label><div><input id="village-stage" name="stage" type="number" min="1" max="${s.maxStage}" step="1" value="${s.maxStage}" required><button class="button gold-button" type="submit">Begin stage ${icon('arrow')}</button></div></form><small>A fresh stage replaces your saved expedition return point.</small></section><section class="panel village-route return-route"><span class="route-number">02 · THE WAY BACK</span><h3>Return portal</h3><p>${s.returnPortal?`Stage ${s.stage} · ${esc(s.map.name)}<br>Same position, surviving monsters, and guardian progress.`:'Teleport here from an expedition to leave a return portal.'}</p><div class="portal-readout">${icon('compass')}<span>${s.returnPortal?`${s.map.progress} / ${s.map.goal} guardian progress`:'No expedition waiting'}</span></div><button class="button" data-action="resume-expedition" ${s.returnPortal?'':'disabled'}>Continue expedition ${icon('arrow')}</button></section><section class="panel village-route rift-route"><span class="route-number">03 · BEYOND THE VEIL</span><h3>Rift portal</h3><p>${s.riftPortal?`${KEYSTONE_RARITIES[s.riftPortal.rarity]} rift · level ${s.riftPortal.itemLevel}<br>${s.riftPortal.modifiers.length} modifiers · one entry remaining`:'Choose a keystone from your pouch to open a single-use portal.'}</p>${s.riftPortal?`<div class="portal-readout">${icon('gem')}<span>Keystone committed · ready to enter</span></div><button class="text-button" data-action="inspect-rift-portal">Review difficulty & rewards</button><button class="button gold-button" data-action="enter-rift">Enter rift · one use ${icon('arrow')}</button>`:'<div class="portal-readout">'+icon('lock')+'<span>No rift open</span></div>'}<small>Death or teleporting out closes the rift. Your normal expedition return point is kept.</small></section></div><section class="panel secondary-panel keystone-altar"><div class="view-section-title"><div><h2>The keystone altar</h2><p>Consume orbs to craft a keystone. Higher rarity adds more difficulty and reward modifiers.</p></div>${icon('sparkles')}</div><label class="keystone-level" for="keystone-level">Keystone level <input id="keystone-level" type="number" min="1" max="${s.maxStage}" step="1" value="${s.maxStage}"> <small>Up to your highest unlocked stage</small></label><div class="keystone-recipes">${KEYSTONE_RECIPES.map(r=>{const can=Object.entries(r.cost).every(([orb,n])=>(s.orbs[orb]||0)>=n);return `<article class="keystone-recipe rarity-${r.rarity}"><span class="item-rarity">${r.label}</span><h3>${[0,'1–2','3–4',6][r.rarity]} modifiers</h3><ul>${Object.entries(r.cost).map(([orb,n])=>`<li class="${(s.orbs[orb]||0)<n?'insufficient':''}">${esc(CRAFT_OPERATIONS[orb].name)} <b>${s.orbs[orb]||0} / ${n}</b></li>`).join('')}</ul><button class="button" data-craft-keystone="${r.rarity}" ${can?'':'disabled'}>Craft ${r.label.toLowerCase()} keystone</button></article>`;}).join('')}</div></section>${keystonePouch(s,page)}`;
}
